WITH with_windows AS (SELECT id, category, brand, price, cost, launch_date, tags, supplier_id, COUNT(stock_qty) OVER w_running AS last3_count_stock_qty, AVG(stock_qty) OVER w_running AS last3_avg_stock_qty, SUM(stock_qty) OVER w_running AS last3_sum_stock_qty FROM products WHERE ARRAY_CONTAINS(tags, 'premium') WINDOW w_running AS (PARTITION BY category ORDER BY cost, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW)) SELECT brand, CASE WHEN last3_avg_stock_qty >= 310 THEN 'HIGH' ELSE 'LOW' END AS last3_avg_stock_qty_tier, CORR(cost, price) AS corr_cost_price, PERCENTILE_APPROX(last3_avg_stock_qty, 0.9) AS last3_avg_stock_qty_p90, PERCENTILE_APPROX(last3_count_stock_qty, ARRAY(0.25, 0.5, 0.75)) AS last3_count_stock_qty_quartiles, ROUND(AVG(last3_count_stock_qty), 2) AS avg_last3_count_stock_qty, MAX(last3_avg_stock_qty) FILTER (WHERE brand = 'Umbrella') AS umbrella_max_last3_avg_stock_qty FROM with_windows GROUP BY GROUPING SETS ((brand, CASE WHEN last3_avg_stock_qty >= 310 THEN 'HIGH' ELSE 'LOW' END), (brand), ()) HAVING last3_avg_stock_qty_p90 > 0 ORDER BY umbrella_max_last3_avg_stock_qty DESC;
